const { values, range, valueInputOption } = $.input;
if (!values || !Array.isArray(values) || values.length === 0) throw new Error('values must be a non-empty 2D array');
const formatted = values.map(row => Array.isArray(row) ? row : [row]);
return {
  body: { range: range || 'Sheet1', majorDimension: 'ROWS', values: formatted },
  queryParams: { valueInputOption: valueInputOption || 'USER_ENTERED', insertDataOption: 'INSERT_ROWS' }
};

const resp = $.steps.appendValues.response || {};
const updates = resp.updates || {};
return {
  spreadsheetId: resp.spreadsheetId || $.input.spreadsheetId,
  updatedRange: updates.updatedRange || resp.tableRange || '',
  updatedRows: updates.updatedRows || 0,
  updatedColumns: updates.updatedColumns || 0,
  updatedCells: updates.updatedCells || 0,
  summary: `Appended ${updates.updatedRows || 0} row${(updates.updatedRows || 0) === 1 ? '' : 's'} to ${$.input.range || 'Sheet1'}`
};
